using System;
using System.IO;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Xunit;
namespace RPCore.Tests
{
    public class MapEditorTests
    {
        static EditorOptions C()=>EditorOptions.Defaults();
        static EditorMap M(string id="map")=>new EditorMap{Id=id,Name="Meu mapa",Objects={new EditorObject{Id="cone",Model="prop_roadcone02a",Pose=new EditorPose{X=100,Y=200,Z=30}}}};
        static MapEditorData D()=>new MapEditorData();
        [Fact]public void DefaultsAreBoundedAndDoNotCreateSceneOrWalletData(){var c=C();Assert.True(c.Valid);Assert.Equal(64,c.MaxObjects);Assert.Equal(12,c.MaxMaps);Assert.Contains("prop_roadcone02a",c.Models);var d=D();Assert.True(d.Valid);Assert.False(d.AutoLoad);Assert.Empty(d.Maps);Assert.Null(d.Selected);}
        [Fact]public void SavingFirstMapCreatesDetachedVersionAndSelection(){var d=D();var m=M();int saves=0;Assert.True(EditorTransactions.Put(ref d,m,-1,C(),_=>saves++));Assert.Equal(1,saves);Assert.Equal("map",d.Selected);Assert.Equal(1,d.Maps[0].Revision);m.Objects[0].Pose.X=999;Assert.Equal(100,d.Maps[0].Objects[0].Pose.X);}
        [Fact]public void DraftChangesAndCancelNeverMutateSavedVersion(){var d=D();EditorTransactions.Put(ref d,M(),-1,C(),_=>{});var draft=EditorRules.Copy(d.Maps[0]);draft.Name="Novo nome";EditorRules.Translate(draft.Objects[0].Pose,1,2,3,0,0,10);Assert.Equal("Meu mapa",d.Maps[0].Name);Assert.Equal(100,d.Maps[0].Objects[0].Pose.X);Assert.Equal(0,d.Maps[0].Objects[0].Pose.RZ);}
        [Fact]public void SaveFailureLeavesAllMapsRevisionsAndSelectionUnchanged(){var d=D();EditorTransactions.Put(ref d,M(),-1,C(),_=>{});string before=JsonConvert.SerializeObject(d);var draft=EditorRules.Copy(d.Maps[0]);draft.Objects.Clear();Assert.Throws<IOException>(()=>EditorTransactions.Put(ref d,draft,1,C(),_=>throw new IOException()));Assert.Equal(before,JsonConvert.SerializeObject(d));}
        [Fact]public void StaleDraftCannotOverwriteNewerSavedRevision(){var d=D();EditorTransactions.Put(ref d,M(),-1,C(),_=>{});var old=EditorRules.Copy(d.Maps[0]);var newer=EditorRules.Copy(old);newer.Name="Mais recente";Assert.True(EditorTransactions.Put(ref d,newer,1,C(),_=>{}));Assert.False(EditorTransactions.Put(ref d,old,1,C(),_=>throw new Exception()));Assert.Equal(2,d.Maps[0].Revision);Assert.Equal("Mais recente",d.Maps[0].Name);}
        [Fact]public void DeleteOnlySelectedMapDisablesAutoloadAndKeepsOthers(){var d=D();EditorTransactions.Put(ref d,M("first"),-1,C(),_=>{});EditorTransactions.Put(ref d,M("second"),-1,C(),_=>{});d.AutoLoad=true;Assert.True(EditorTransactions.Delete(ref d,"second",1,_=>{}));Assert.Single(d.Maps);Assert.Equal("first",d.Maps[0].Id);Assert.Null(d.Selected);Assert.False(d.AutoLoad);Assert.True(d.Valid);}
        [Fact]public void FailedOrStaleDeletionNeverChangesLibrary(){var d=D();EditorTransactions.Put(ref d,M(),-1,C(),_=>{});Assert.False(EditorTransactions.Delete(ref d,"map",0,_=>throw new Exception()));string before=JsonConvert.SerializeObject(d);Assert.Throws<IOException>(()=>EditorTransactions.Delete(ref d,"map",1,_=>throw new IOException()));Assert.Equal(before,JsonConvert.SerializeObject(d));}
        [Fact]public void ImportedCopyRemapsAllIdsAndPreservesUnknownFieldsAndSource(){var m=M();m.Points.Add(P("shop",EditorPointKind.Grocery,10));var j=JObject.FromObject(m);j["FutureMap"]="keep";j["Objects"][0]["FutureObject"]=42;j["Objects"][0]["Pose"]["FuturePose"]=77;j["Points"][0]["FuturePoint"]="keep";m=j.ToObject<EditorMap>();string before=JsonConvert.SerializeObject(m);var n=EditorRules.ImportCopy(m);Assert.NotEqual(m.Id,n.Id);Assert.NotEqual(m.Objects[0].Id,n.Objects[0].Id);Assert.NotEqual(m.Points[0].Id,n.Points[0].Id);Assert.Equal(0,n.Revision);Assert.Equal("keep",(string)n.Extra["FutureMap"]);Assert.Equal(42,(int)n.Objects[0].Extra["FutureObject"]);Assert.Equal(77,(int)n.Objects[0].Pose.Extra["FuturePose"]);Assert.Equal("keep",(string)n.Points[0].Extra["FuturePoint"]);Assert.Equal(before,JsonConvert.SerializeObject(m));Assert.True(n.Valid);}
        [Fact]public void ExportRoundtripKeepsPropsRotationCollisionAndPointFlags(){var m=M();m.Objects[0].Collision=true;m.Objects[0].Pose.RX=20;m.Objects[0].Pose.RY=30;m.Objects[0].Pose.RZ=40;var p=P("icon",EditorPointKind.Marker,0);p.Sprite=40;p.Color=7;p.ShortRange=false;p.Legend=false;m.Points.Add(p);var n=JsonConvert.DeserializeObject<EditorMap>(JsonConvert.SerializeObject(m));Assert.True(n.Valid);Assert.True(n.Objects[0].Collision);Assert.Equal(40,n.Objects[0].Pose.RZ);Assert.False(n.Points[0].ShortRange);Assert.False(n.Points[0].Legend);Assert.Equal(7,n.Points[0].Color);}
        [Fact]public void EmptyLibraryRemainsEmptyUntilExplicitMutation(){var d=JsonConvert.DeserializeObject<MapEditorData>("{\"Format\":1,\"FutureProfile\":42}");Assert.True(d.Valid);Assert.Empty(d.Maps);EditorTransactions.Put(ref d,M(),-1,C(),_=>{});Assert.Equal(42,(int)d.Extra["FutureProfile"]);}
        [Theory][InlineData("../escape")][InlineData("..")][InlineData("a/b")][InlineData("a\\b")][InlineData("file.json")][InlineData("a:b")][InlineData("foo\n")][InlineData("")]
        public void ExportNamesCannotEscapeDirectoryOrInjectExtension(string name){Assert.False(EditorRules.FileName(name));}
        [Theory][InlineData("meu_mapa")][InlineData("Casa-01")][InlineData("mapa123")]
        public void SafeExportNamesAccepted(string name){Assert.True(EditorRules.FileName(name));}
        [Theory][InlineData(float.NaN)][InlineData(float.PositiveInfinity)][InlineData(15000)][InlineData(-15000)]
        public void InvalidWorldCoordinatesProtected(float x){var m=M();m.Objects[0].Pose.X=x;Assert.False(m.Valid);Assert.Null(EditorRules.ImportCopy(m));var d=D();Assert.False(EditorTransactions.Put(ref d,m,-1,C(),_=>throw new Exception()));}
        [Fact]public void ModelNameCannotBeScriptPathOrArbitraryCode(){foreach(string model in new[]{"../evil.dll","abc/def","x;whoami","a b",""})Assert.False(EditorRules.ModelNameSafe(model));Assert.True(EditorRules.ModelNameSafe("prop_roadcone02a"));}
        [Fact]public void DuplicateIdsIncludingAcrossObjectsAndPointsAreRejected(){var m=M();m.Points.Add(P("cone",EditorPointKind.Marker,1));Assert.False(m.Valid);m=M();m.Objects.Add(EditorRules.Copy(m.Objects[0]));Assert.False(m.Valid);var d=D();d.Maps.Add(M());d.Maps.Add(M());Assert.False(d.Valid);}
        [Fact]public void UnknownFormatNullArraysAndBrokenSelectionAreProtected(){var d=D();d.Format=2;Assert.False(d.Valid);Assert.False(EditorTransactions.Apply(ref d,_=>true,_=>throw new Exception()));d=D();d.AutoLoad=true;Assert.False(d.Valid);d=D();d.Selected="missing";Assert.False(d.Valid);var m=M();m.Objects=null;Assert.False(m.Valid);m=M();m.Points=null;Assert.False(m.Valid);}
        [Fact]public void ConfigurationCapsPreventLargeMapLibrariesAndObjects(){var d=D();var c=C();c.MaxMaps=1;Assert.True(EditorTransactions.Put(ref d,M(),-1,c,_=>{}));Assert.False(EditorTransactions.Put(ref d,M("second"),-1,c,_=>throw new Exception()));c=C();c.MaxObjects=1;var m=M();m.Objects.Add(new EditorObject{Id="two",Model="prop_bin_01a",Pose=new EditorPose{Z=10}});Assert.False(EditorTransactions.Put(ref d,m,1,c,_=>throw new Exception()));}
        [Fact]public void MoveIsAtomicAndRotationWrapsWithoutFreezingTransform(){var p=new EditorPose{X=100,Y=100,Z=30,RZ=179};Assert.True(EditorRules.Translate(p,1,2,3,0,0,5));Assert.Equal(101,p.X);Assert.Equal(33,p.Z);Assert.Equal(-176,p.RZ);string before=JsonConvert.SerializeObject(p);Assert.False(EditorRules.Translate(p,float.NaN,0,0));Assert.False(EditorRules.Translate(p,21,0,0));Assert.Equal(before,JsonConvert.SerializeObject(p));p.X=14999;before=JsonConvert.SerializeObject(p);Assert.False(EditorRules.Translate(p,2,0,0));Assert.Equal(before,JsonConvert.SerializeObject(p));}
        static EditorPoint P(string id,EditorPointKind kind,float x)=>new EditorPoint{Id=id,Name="Ponto",Kind=kind,Pose=new EditorPose{X=x,Y=10,Z=30}};
        [Fact]public void ServiceDuplicatesUseSourceFiveMeterRadiusWithoutBlockingDifferentTypes(){var m=M();m.Points.Add(P("a",EditorPointKind.Grocery,0));Assert.False(EditorRules.CanAddPoint(m,P("b",EditorPointKind.Grocery,4.99f),32));Assert.True(EditorRules.CanAddPoint(m,P("b",EditorPointKind.Grocery,5),32));Assert.True(EditorRules.CanAddPoint(m,P("b",EditorPointKind.Fuel,0),32));Assert.False(EditorRules.CanAddPoint(m,P("a",EditorPointKind.Fuel,10),32));}
        [Fact]public void SemanticInvalidPointAndServiceKindCannotBeSaved(){var p=P("a",(EditorPointKind)99,0);Assert.False(p.Valid);p=P("a",EditorPointKind.Marker,0);p.Color=86;Assert.False(p.Valid);p=P("a",EditorPointKind.Marker,0);p.Sprite=1001;Assert.False(p.Valid);p.Name="\n";Assert.False(p.Valid);}
        [Fact]public void RevisionOverflowDoesNotOverwriteSavedScene(){var d=D();var m=M();m.Revision=long.MaxValue;d.Maps.Add(m);Assert.True(d.Valid);Assert.False(EditorTransactions.Put(ref d,EditorRules.Copy(m),long.MaxValue,C(),_=>throw new Exception()));Assert.Equal(long.MaxValue,d.Maps[0].Revision);}
        [Fact]public void RealAtomicFileRoundtripAndBackupPreservePreviousMap(){string dir=Path.Combine(Path.GetTempPath(),"rpcore-editor-"+Guid.NewGuid().ToString("N"));try{var f=new JsonFiles();string path=Path.Combine(dir,"MapEditor.json");var d=D();EditorTransactions.Put(ref d,M(),-1,C(),n=>f.Write(path,n));var first=File.ReadAllText(path);var draft=EditorRules.Copy(d.Maps[0]);draft.Name="Nova versao";EditorTransactions.Put(ref d,draft,1,C(),n=>f.Write(path,n));Assert.Equal(first,File.ReadAllText(path+".bak"));var loaded=f.Read<MapEditorData>(path,()=>null);Assert.True(loaded.Valid);Assert.Equal("Nova versao",loaded.Maps[0].Name);}finally{if(Directory.Exists(dir))Directory.Delete(dir,true);}}
        [Fact]public void CorruptedJsonIsNeverReplacedByEmptyLibrary(){string dir=Path.Combine(Path.GetTempPath(),"rpcore-editor-"+Guid.NewGuid().ToString("N"));try{Directory.CreateDirectory(dir);string path=Path.Combine(dir,"MapEditor.json");File.WriteAllText(path,"{");var files=new JsonFiles();Assert.ThrowsAny<Exception>(()=>files.Read<MapEditorData>(path,D));Assert.Throws<IOException>(()=>files.Write(path,D()));Assert.Equal("{",File.ReadAllText(path));}finally{Directory.Delete(dir,true);}}
        [Fact]public void EditorGateNeverOverlapsWithMissionsOrPolice(){var g=new ShiftGate();Assert.True(g.Acquire("map_editor"));foreach(string name in new[]{"halloween","studio_heist","traffic","custody","pizza"})Assert.False(g.Acquire(name));g.Release("other");Assert.Equal("map_editor",g.Owner);g.Release("map_editor");Assert.True(g.Acquire("pizza"));}
    }
}
